import { useEffect, useState, useSyncExternalStore, type RefObject } from "react";

/**
 * Animation helpers for components that need no animation library: spring
 * easings for CSS transitions and the Web Animations API, plus the two browser
 * checks those components share. Installed alongside any component that uses it.
 */

export type SpringOptions = {
  stiffness?: number;
  damping?: number;
  mass?: number;
};

/** A spring as a CSS timing: `duration` in milliseconds, `easing` as `linear(…)`. */
export type Timing = { duration: number; easing: string };

/** How many points of the spring's curve the easing samples. */
const SAMPLES = 48;

/** The time constant multiple at which a spring is within 0.1% of its target. */
const SETTLED = Math.log(1000);

/**
 * Browsers without `linear()` get a plain ease instead: the Web Animations API
 * throws on an easing it can't parse, rather than ignoring it as CSS would.
 */
const supportsLinearEasing = () =>
  typeof CSS === "undefined" || CSS.supports("transition-timing-function", "linear(0, 1)");

/** The response of a spring released from rest, as a CSS easing. */
export function springTiming({ stiffness = 100, damping = 10, mass = 1 }: SpringOptions = {}): Timing {
  const natural = Math.sqrt(stiffness / mass);
  const ratio = Math.min(damping / (2 * Math.sqrt(stiffness * mass)), 1);
  const decay = ratio * natural;
  const seconds = SETTLED / decay;
  if (!supportsLinearEasing()) return { duration: Math.round(seconds * 1000), easing: "ease-out" };

  const damped = natural * Math.sqrt(1 - ratio * ratio);
  const position = (t: number) =>
    ratio < 1
      ? 1 - Math.exp(-decay * t) * (Math.cos(damped * t) + (decay / damped) * Math.sin(damped * t))
      : 1 - Math.exp(-natural * t) * (1 + natural * t);

  const points = Array.from({ length: SAMPLES + 1 }, (_, i) =>
    i === SAMPLES ? "1" : position((i / SAMPLES) * seconds).toFixed(4),
  );
  return { duration: Math.round(seconds * 1000), easing: `linear(${points.join(",")})` };
}

/** A spring described by how long it takes and how much it bounces (0 to 1). */
export function bounceTiming(seconds: number, bounce: number): Timing {
  const ratio = 1 - bounce;
  const natural = SETTLED / (ratio * seconds);
  return springTiming({ stiffness: natural * natural, damping: 2 * ratio * natural });
}

const REDUCED_MOTION = "(prefers-reduced-motion: reduce)";

const subscribeToReducedMotion = (onChange: () => void) => {
  const query = window.matchMedia(REDUCED_MOTION);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};

/** Whether the visitor asked for less motion. False during server rendering. */
export const usePrefersReducedMotion = () =>
  useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION).matches,
    () => false,
  );

/** The same check, for code running outside render. */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia(REDUCED_MOTION).matches;

/**
 * Whether an element is on screen. `amount` is the share of it that must show.
 * With `once` it stays true after the first time.
 */
export function useInView(
  ref: RefObject<Element | null>,
  { amount = 0, once = false }: { amount?: number; once?: boolean } = {},
): boolean {
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
        if (entry.isIntersecting && once) observer.disconnect();
      },
      { threshold: amount },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref, amount, once]);

  return inView;
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

/**
 * Positioning has to happen before the browser paints, or the tooltip shows up
 * at its placeholder coordinates for one frame and then jumps into place.
 * useLayoutEffect warns when it runs on the server, and TooltipContent renders
 * nothing until the trigger has committed, so falling back to useEffect there
 * costs nothing.
 */
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

// ==========================================
// 1. CONTEXT
// ==========================================
interface TooltipContextType {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  delayDuration: number;
  /**
   * The trigger node itself, held in state rather than a ref. A ref shared
   * through context makes every read of this context a ref read during render;
   * a plain node lets the content position and portal itself without one.
   */
  trigger: HTMLDivElement | null;
  setTrigger: React.Dispatch<React.SetStateAction<HTMLDivElement | null>>;
}
const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

// ==========================================
// 2. PROVIDER (Optional: For wrapping the app)
// ==========================================
export function TooltipProvider({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

// ==========================================
// 3. TOOLTIP ROOT (State Manager)
// ==========================================
export interface TooltipProps {
  children: React.ReactNode;
  delayDuration?: number;
}

export function Tooltip({ children, delayDuration = 200 }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const [trigger, setTrigger] = useState<HTMLDivElement | null>(null);

  // The open/close delay is owned by the trigger, not shared through context:
  // a timeout ref captured by a context handler would make every read of this
  // context look like a ref read during render.
  const value = useMemo(
    () => ({ open, setOpen, delayDuration, trigger, setTrigger }),
    [open, delayDuration, trigger],
  );

  return (
    <TooltipContext.Provider value={value}>
      {children}
    </TooltipContext.Provider>
  );
}

// ==========================================
// 4. TRIGGER
// ==========================================
export interface TooltipTriggerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean;
}

export function TooltipTrigger({
  children,
  className,
  ...props
}: TooltipTriggerProps) {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("TooltipTrigger must be used within a Tooltip");

  const { open, setOpen, delayDuration, setTrigger } = context;
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleOpen = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setOpen(true), delayDuration);
  }, [setOpen, delayDuration]);

  const handleClose = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(false);
  }, [setOpen]);

  useEffect(
    () => () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    },
    [],
  );

  return (
    <div
      ref={setTrigger}
      className={cn("inline-block", className)}
      tabIndex={0}
      aria-haspopup="dialog"
      aria-expanded={open}
      {...props}
      onMouseEnter={(e) => {
        handleOpen();
        props.onMouseEnter?.(e);
      }}
      onMouseLeave={(e) => {
        handleClose();
        props.onMouseLeave?.(e);
      }}
      onFocus={(e) => {
        handleOpen();
        props.onFocus?.(e);
      }}
      onBlur={(e) => {
        handleClose();
        props.onBlur?.(e);
      }}
    >
      {children}
    </div>
  );
}

// ==========================================
// 5. CONTENT (Portal Renderer)
// ==========================================
export interface TooltipContentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
  sideOffset?: number;
  /** Whether to render a pointer arrow anchoring to the trigger. Defaults to false. */
  showArrow?: boolean;
  /** Custom classes for the pointer arrow element. */
  arrowClassName?: string;
  /** Whether to enable a smooth pull-out animation sliding gently out from the trigger. Can also be set to "staggered" for sequential icon, title, and description entrance, "expand" for dynamic height/width expansion, or "pop" for a snappy spring popup emergence. */
  animated?: boolean | "pull-out" | "staggered" | "expand" | "pop";
  /** Whether to animate child elements (icon -> title -> description) in a staggered cascade. Defaults to false. */
  staggered?: boolean;
  /** Whether to start with only title space and smoothly expand height (for top/bottom) or width (for left/right) to unveil the description. Defaults to false. */
  expand?: boolean;
  /** Optional title header displayed in bold. */
  title?: React.ReactNode;
  /** Optional description text. */
  description?: React.ReactNode;
  /** Shorthand alias for description. */
