    start: "-top-1 left-3",
    end: "-top-1 right-3",
  },
  left: {
    center: "-right-1 top-1/2 -translate-y-1/2",
    start: "-right-1 top-3",
    end: "-right-1 bottom-3",
  },
  right: {
    center: "-left-1 top-1/2 -translate-y-1/2",
    start: "-left-1 top-3",
    end: "-left-1 bottom-3",
