  effect?: ShardsEffect;
  effectMode?: ShardsEffectMode;
  /**
   * Whether a `continuous` effect is running. Defaults to: slider at full,
   * toggle on, select / colour once something has been picked.
   */
  effectActive?: boolean;
}

