              backgroundImage:
                'url("https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_1200,c_limit/v1790146209/photo-1470071459604-3b5ec3a7fe05-1790146212205.jpg")',
              backgroundSize: "cover",
              backgroundPosition: "center",
              filter: "url(#glass-blur)",
              transform: "scale(1.1)",
            }}
          />

          {/* Layer 1: Contrast overlay & soft backdrop blur */}
          <div className="absolute inset-0 z-10 pointer-events-none bg-black/30 dark:bg-black/45 backdrop-blur-[2px]" />

          {/* Layer 2: Ambient Drop Shadow & Subtle Glow */}
          <div
            className="absolute inset-0 z-20 pointer-events-none rounded-[22px] sm:rounded-[28px]"
            style={{
              boxShadow:
                "0 20px 50px rgba(0, 0, 0, 0.4), 0 0 20px rgba(255, 255, 255, 0.08)",
            }}
          />

          {/* Layer 3: Specular Inner Border Highlight (Light: bright glass bevel, Dark: sleek darkish rim) */}
          <div
            className="absolute inset-0 z-30 pointer-events-none rounded-[22px] sm:rounded-[28px] border border-white/40 dark:border-white/15"
            style={{
              boxShadow:
                "inset 2px 2px 2px 0 rgba(255, 255, 255, 0.45), inset -2px -2px 2px 0 rgba(255, 255, 255, 0.3)",
            }}
          />

          {/* Layer 4: Modal Dialog Content */}
          <div className="relative z-40 p-3.5 sm:p-5">
            {(title || icon || badge) && (
              <ModalHeader
                className="border-none p-2 sm:p-4 pb-2 flex items-start justify-between gap-3 pr-10 sm:pr-12"
                title={
                  <div className="flex items-center gap-2.5 sm:gap-3">
                    <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-xl sm:rounded-2xl flex items-center justify-center shrink-0 shadow-sm transition-all border bg-white/20 border-white/30 dark:bg-white/10 dark:border-white/15 text-white backdrop-blur-md">
                      {icon ?? <Sparkles className="w-5 h-5 sm:w-6 sm:h-6 text-white drop-shadow-sm" />}
                    </div>
                    <div className="flex flex-col min-w-0">
                      {typeof title === "string" ? (
                        <h2 className="text-lg sm:text-xl font-semibold tracking-tight text-white drop-shadow-sm truncate">
                          {title}
                        </h2>
                      ) : (
                        title
                      )}
                      {badge && (
                        <span className="text-[11px] sm:text-xs font-semibold px-2 sm:px-2.5 py-0.5 mt-0.5 rounded-full w-fit bg-white/20 border border-white/30 dark:bg-white/10 dark:border-white/15 text-white backdrop-blur-md">
                          {badge}
                        </span>
                      )}
                    </div>
                  </div>
                }
              />
            )}
            {(description || children) && (
              <ModalBody className="p-2 sm:p-4 pt-1 sm:pt-2 space-y-2">
                {description && (
                  <p className="text-white/85 leading-relaxed text-xs sm:text-sm font-normal">
                    {description}
                  </p>
                )}
                {children}
              </ModalBody>
            )}
            {(confirmText || cancelText) && (
              <ModalFooter className="border-none p-2 sm:p-4 pt-3 sm:pt-4 flex flex-col-reverse sm:flex-row gap-2 sm:justify-end">
                {cancelText && (
                  <button
                    type="button"
                    onClick={onCancel ?? handleClose}
                    className="w-full sm:w-auto px-4 sm:px-5 py-2 sm:py-2.5 rounded-xl text-xs sm:text-sm font-semibold text-white bg-black/25 hover:bg-black/35 dark:bg-white/10 dark:hover:bg-white/20 border border-white/20 dark:border-white/15 backdrop-blur-md transition-all cursor-pointer text-center justify-center flex items-center"
                  >
                    {cancelText}
                  </button>
                )}
                {confirmText && (
                  <button
                    type="button"
                    onClick={onConfirm ?? handleClose}
                    className="w-full sm:w-auto px-5 sm:px-6 py-2 sm:py-2.5 rounded-xl text-xs sm:text-sm font-semibold bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg shadow-primary/25 active:scale-95 transition-all cursor-pointer text-center justify-center flex items-center"
                  >
                    {confirmText}
                  </button>
                )}
              </ModalFooter>
            )}
          </div>
        </div>
      );
    }

    if (activeVariant === "standard" && (title || description || confirmText)) {
      return (
        <div className="p-2 sm:p-4">
          {(title || icon || badge) && (
            <ModalHeader
              className="border-none p-4 pb-2 flex items-start justify-between gap-4"
              title={
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm transition-all border bg-primary/10 text-primary border-primary/30">
                    {icon ?? <AlertCircle className="w-6 h-6" />}
                  </div>
                  <div className="flex flex-col">
                    {typeof title === "string" ? (
                      <h2 className="text-xl font-semibold tracking-tight text-foreground">
                        {title}
                      </h2>
                    ) : (
                      title
                    )}
                    {badge && (
                      <span className="text-xs font-semibold text-emerald-600 dark:text-emerald-400">
                        {badge}
                      </span>
                    )}
                  </div>
                </div>
              }
            />
          )}
          {(description || children) && (
            <ModalBody className="p-4 pt-2 space-y-2">
              {description && (
                <p className="text-muted-foreground leading-relaxed text-sm sm:text-base font-normal">
                  {description}
                </p>
              )}
              {children}
            </ModalBody>
          )}
          {(confirmText || cancelText) && (
            <ModalFooter className="border-none p-4 pt-4 flex flex-col-reverse sm:flex-row gap-2 sm:justify-end">
              {cancelText && (
                <button
                  type="button"
                  onClick={onCancel ?? handleClose}
                  className="px-5 py-2.5 rounded-xl text-sm font-semibold text-muted-foreground hover:bg-muted transition-colors cursor-pointer"
                >
                  {cancelText}
                </button>
              )}
              {confirmText && (
                <button
                  type="button"
                  onClick={onConfirm ?? handleClose}
                  className="px-6 py-2.5 rounded-xl text-sm font-semibold shadow-lg shadow-primary/20 active:scale-95 transition-all bg-primary hover:bg-primary/90 text-primary-foreground cursor-pointer"
                >
                  {confirmText}
                </button>
              )}
            </ModalFooter>
          )}
        </div>
      );
    }

    return children;
  };

  const overlay = (
    <div
      className={cn(
        "fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300 ease-in-out",
        isVisible ? "opacity-100" : "opacity-0 pointer-events-none",
        activeVariant !== "liquid-glass" && "backdrop-blur-[3px]",
        isVisible ? "bg-black/50" : "bg-black/0",
        variantOverlayClass[activeVariant],
        overlayClassName,
      )}
      onClick={handleClose}
      role="presentation"
    >
      <div
        className={cn(
          "relative flex max-h-full w-full max-w-lg flex-col overflow-hidden rounded-2xl transition-all duration-300 ease-in-out",
          activeVariant !== "liquid-glass" && "bg-background shadow-xl",
          activeVariant === "liquid-glass"
            ? isVisible
              ? "opacity-100 scale-100"
              : "opacity-0 scale-95 pointer-events-none"
            : isVisible
              ? "opacity-100 translate-y-0 scale-100"
              : "opacity-0 -translate-y-8 scale-95",
          variantContentClass[activeVariant],
          contentClassName,
        )}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        {...ariaProps}
      >
        {!isHideClose &&
          (primaryCloseButton ? (
            <button
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleClose();
              }}
              data-modal-close
              type="button"
              aria-label="Close"
              className={cn(
                "p-1.5 rounded-md absolute top-3.5 right-3.5 sm:top-4 sm:right-4 cursor-pointer transition-colors duration-200 z-50",
                activeVariant === "liquid-glass"
                  ? "text-white/80 hover:text-white bg-white/20 hover:bg-white/30 dark:bg-black/50 dark:hover:bg-black/70 dark:border dark:border-white/15 rounded-full backdrop-blur-md"
                  : "bg-primary/10 text-primary hover:bg-primary/20"
              )}
            >
              <X className="h-5 w-5 ml-[1px]" />
            </button>
          ) : (
            <button
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleClose();
              }}
              data-modal-close
              type="button"
              aria-label="Close"
              className={cn(
                "absolute top-3.5 right-3.5 sm:top-4 sm:right-4 cursor-pointer transition-colors duration-200 z-50",
                activeVariant === "liquid-glass"
                  ? "text-white/80 hover:text-white bg-white/20 hover:bg-white/30 dark:bg-black/50 dark:hover:bg-black/70 dark:border dark:border-white/15 p-1.5 rounded-full backdrop-blur-md"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <X className="h-5 w-5" />
            </button>
          ))}
        <ModalLabelContext.Provider value={labelId}>
          {/* min-h-0 lets this shrink below its content so the body can
              scroll; flex-1 fills a panel given a fixed height. */}
          <div className="flex min-h-0 flex-1 flex-col">{renderVariantContent()}</div>
        </ModalLabelContext.Provider>
      </div>
    </div>
  );

  return (
    <>
      <span ref={setAnchor} hidden aria-hidden="true" />
      <LiquidGlassSvgFilter />
      {createPortal(overlay, portalTarget)}
    </>
  );
}

export type ModalSectionProps = {
  title?: React.ReactNode;
  className?: string;
  children?: React.ReactNode;
};

export function ModalHeader({
  title,
  className,
  children,
}: ModalSectionProps) {
  const labelId = useContext(ModalLabelContext);
  return (
    <div
      id={labelId || undefined}
      className={cn(
        // shrink-0: in the panel's flex column the explicit min-h would
        // otherwise let a tall body squeeze a two-line header down to 56px.
        "shrink-0 px-6 py-4 text-lg font-semibold border-b border-border/50 flex items-center justify-between min-h-[56px]",
        className,
      )}
    >
      <div className="flex-1 flex items-center gap-3">
        {title && typeof title === "string" ? (
          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        ) : (
          title
        )}
        {children}
      </div>
    </div>
  );
}

export function ModalFooter({ className, children }: ModalSectionProps) {
  return (
    <div className={cn("flex shrink-0 justify-end gap-2 p-4", className)}>
      {children}
    </div>
  );
}

export function ModalBody({ className, children }: ModalSectionProps) {
  return (
    <div className={cn("p-4 max-h-[calc(100vh-150px)] overflow-auto", className)}>
      {children}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AlertCircle, Check, ChevronDown, Search, X } from "lucide-react";
import React, { forwardRef, useEffect, useMemo, useRef, useState } from "react";
import { getThemeStyles } from "./select-theme";

// ==========================================
// DYNAMIC THEME ENGINE
// ==========================================
export type SelectColor = "indigo" | "rose" | "emerald" | "zinc" | string;
export type SelectVariant = "default" | "filled" | "underlined" | "glow" | "glass" | "liquid-glass";
export type SelectSize = "sm" | "md" | "lg";

// ==========================================
// SELECT COMPONENT
// ==========================================
export interface SelectOption {
  label: string;
  value: string;
  icon?: React.ElementType;
  group?: string; // Added for nested/grouped options
}

// Walks up the tree to the first ancestor that clips its overflow (a modal
// shell, a scroll pane, a card with overflow-hidden). That element — not the
// viewport — is what actually crops the dropdown, so it defines the space the
// menu has to work with. Returns null when nothing clips, meaning the viewport
// is the only bound. Only overflow-y counts: the menu grows vertically, and a
// box that clips just sideways (overflow-x: clip, e.g. a slide-in stage) leaves
// it free to hang below — treating that as a clip flipped the menu up into it.
const getClippingRect = (el: HTMLElement): DOMRect | null => {
  let node = el.parentElement;
  while (node && node !== document.body) {
    const { overflowY } = window.getComputedStyle(node);
    if (/(auto|scroll|hidden|clip)/.test(overflowY)) {
      return node.getBoundingClientRect();
    }
    node = node.parentElement;
  }
  return null;
};

/** Everything the two selection modes share. */
interface SelectBlockBaseProps {
  options: SelectOption[];
  placeholder?: string;
  variant?: SelectVariant;
  color?: SelectColor;
  inputSize?: SelectSize;
  label?: string;
  helperText?: string;
  error?: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  className?: string;
  /** Adds a filter box above the options. */
  searchable?: boolean;
}

/** The default: one option at a time, so the value is a plain string. */
export interface SelectBlockSingleProps extends SelectBlockBaseProps {
  multiple?: false;
  value?: string;
  onChange?: (value: string) => void;
}

/** `multiple` — value and callback both deal in arrays. */
export interface SelectBlockMultipleProps extends SelectBlockBaseProps {
  multiple: true;
  value?: string[];
  onChange?: (value: string[]) => void;
}

/**
 * Discriminated on `multiple`, so a single select hands your callback a
 * `string` and a multi select hands it a `string[]` — neither needs a cast,
 * and passing a `setState` straight in just works.
 */
export type SelectBlockProps = SelectBlockSingleProps | SelectBlockMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type SelectBlockImplProps = SelectBlockBaseProps & {
  multiple?: boolean;
  value?: string | string[];
  onChange?: (value: string | string[]) => void;
};

const SelectBlockImpl = forwardRef<HTMLDivElement, SelectBlockImplProps>(
  (
    {
      options = [],
      value,
      onChange,
      placeholder = "Select an option",
      variant = "default",
      color = "primary",
      inputSize = "md",
      label,
      helperText,
      error,
      icon,
      disabled = false,
      className,
      multiple = false,
      searchable = false,
    },
    ref,
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [dropUp, setDropUp] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const selectRef = useRef<HTMLDivElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const { theme, style } = getThemeStyles(color);

    // selectRef drives the click-outside and drop-direction logic, so the
    // forwarded ref is mirrored onto it rather than replacing it.
    React.useImperativeHandle(ref, () => selectRef.current as HTMLDivElement);

    const hasError = Boolean(error);

    // Filter options based on search
    const filteredOptions = useMemo(() => {
      if (!searchQuery) return options;
      return options.filter((opt) =>
        opt.label.toLowerCase().includes(searchQuery.toLowerCase()),
      );
    }, [options, searchQuery]);

    // Group options if "group" property is provided
    const groupedOptions = useMemo(() => {
      return filteredOptions.reduce(
        (acc, opt) => {
          const group = opt.group || "ungrouped";
          if (!acc[group]) acc[group] = [];
          acc[group].push(opt);
          return acc;
        },
        {} as Record<string, SelectOption[]>,
      );
    }, [filteredOptions]);

    // Focus search input automatically when opened
    useEffect(() => {
      if (isOpen && searchable && searchInputRef.current) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
      if (!isOpen) setSearchQuery("");
    }, [isOpen, searchable]);

    // Close dropdown on click outside
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          selectRef.current &&
          !selectRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
        }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () =>
        document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Decide which way the menu opens *before* it becomes visible, so it never
    // renders in the wrong place for a frame. The menu is always mounted (it is
    // only hidden via opacity), so its height is measurable while closed.
    const handleToggle = () => {
      if (!isOpen && selectRef.current) {
        const trigger = selectRef.current.getBoundingClientRect();
        const clip = getClippingRect(selectRef.current);
        const menuHeight = dropdownRef.current?.offsetHeight ?? 240;

        const bottomBound = Math.min(
          window.innerHeight,
          clip ? clip.bottom : Number.POSITIVE_INFINITY,
        );
        const topBound = Math.max(0, clip ? clip.top : 0);

        const spaceBelow = bottomBound - trigger.bottom - 8;
        const spaceAbove = trigger.top - topBound - 8;

        // Only flip when below genuinely can't fit and above is roomier.
        setDropUp(spaceBelow < menuHeight && spaceAbove > spaceBelow);
      }
      setIsOpen(!isOpen);
    };

    const handleSelect = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple) {
        const currentValues = Array.isArray(value) ? value : [];
        const newValues = currentValues.includes(optValue)
          ? currentValues.filter((v) => v !== optValue)
          : [...currentValues, optValue];
        if (onChange) onChange(newValues);
      } else {
        if (onChange) onChange(optValue);
        setIsOpen(false);
      }
    };

    const handleRemoveTag = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple && Array.isArray(value)) {
        if (onChange) onChange(value.filter((v) => v !== optValue));
      }
    };

    // --- Size Classes ---
    const sizeClasses = {
      sm: {
        wrapper: "min-h-9 px-3 py-1.5",
        text: "text-xs",
        icon: "w-3.5 h-3.5",
        option: "px-3 py-2 text-xs",
        tag: "px-1.5 py-0.5 text-[10px]",
      },
      md: {
        wrapper: "min-h-11 px-4 py-2.5",
        text: "text-sm",
        icon: "w-4 h-4",
        option: "px-4 py-2.5 text-sm",
        tag: "px-2 py-1 text-xs",
      },
      lg: {
        wrapper: "min-h-14 px-5 py-3.5",
        text: "text-base",
        icon: "w-5 h-5",
        option: "px-5 py-3 text-base",
        tag: "px-2.5 py-1 text-sm",
      },
    };
    const s = sizeClasses[inputSize as SelectSize] || sizeClasses.md;

    // --- Variant Styles ---
    const getVariantStyles = () => {
      const baseWrapper = cn(
        "relative flex items-center justify-between w-full transition-all duration-300 cursor-pointer outline-none",
        s.wrapper,
      );

      if (disabled)
        return {
          wrapper: cn(
            baseWrapper,
            "opacity-50 cursor-not-allowed border border-border bg-muted",
          ),
          active: "",
        };
      if (hasError)
        return {
          wrapper: cn(
            baseWrapper,
            "border border-red-500 bg-background",
            variant === "underlined" && "border-0 border-b-2 rounded-none",
            variant !== "underlined" && "rounded-xl",
          ),
          active: "ring-4 ring-red-500/10",
        };

      switch (variant) {
        case "filled":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-muted border border-transparent rounded-xl",
            ),
            active: cn("bg-background ring-4", theme.ring),
          };
        case "underlined":
          return {
            wrapper: cn(
              baseWrapper,
              "border-b-2 border-border bg-transparent rounded-none px-0",
            ),
            active: theme.ring.split(" ")[1],
          };
        case "glow":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: theme.glow,
          };
        case "liquid-glass":
          return {
            wrapper: cn(
              baseWrapper,
